const before = angle;
await sleep(120);
assert(angle === before, "Durunca animasyon gerçekten durmalı: cancelAnimationFrame(frameId) kullan.");
click("#toggle");
assert(running === true && $("#toggle").textContent.trim() === "Durdur", "İkinci tıklamada running true olmalı ve düğme 'Durdur' yazmalı.");

