const TOTAL = 10;
let timeLeft = 10;
const bar = document.querySelector("#time-bar");
const info = document.querySelector("#info");

function step(dt) {
  // süreyi azalt, çubuğu ve yazıyı güncelle
  timeLeft = Math.max(0, timeLeft - dt);
  bar.style.width = timeLeft * 100 / TOTAL + "%";
  if (timeLeft === 0) {
    info.textContent = "Süre doldu!";
    bar.classList.add("empty");
  } else {
    info.textContent = `Süre: ${Math.ceil(timeLeft)} sn`;
  }
}

let last = 0;
function loop(time) {
  if (!last) last = time;
  step((time - last) / 1000);
  last = time;
  if (timeLeft > 0) requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

check.js:
const width = () => parseFloat($("#time-bar").style.width);
timeLeft = 10;
step(2.5);
assert(timeLeft === 7.5, "step(2.5) timeLeft'i 2.5 azaltmalı (10 → 7.5).");
assert(Math.abs(width() - 75) < 0.01 && /%$/.test($("#time-bar").style.width), "Çubuğun genişliği '75%' olmalı.");
assert($("#info").textContent.trim() === "Süre: 8 sn", "#info 'Süre: 8 sn' yazmalı (7.5 yukarı yuvarlanır).");
step(0.5);
assert(Math.abs(width() - 70) < 0.01 && $("#info").textContent.trim() === "Süre: 7 sn", "7 saniye kalınca çubuk '70%' ve yazı 'Süre: 7 sn' olmalı.");
step(20);
assert(timeLeft === 0, "Süre 0'ın altına inmemeli.");
assert(width() === 0, "Süre bitince çubuğun genişliği 0% olmalı.");
assert($("#info").textContent.trim() === "Süre doldu!", "Süre bitince #info 'Süre doldu!' yazmalı.");
assert($("#time-bar").classList.contains("empty"), "Süre bitince çubuğa empty sınıfı eklenmeli.");
$("#time-bar").classList.remove("empty");
timeLeft = 4;
step(1);
assert(Math.abs(width() - 30) < 0.01 && !$("#time-bar").classList.contains("empty"), "Süre bitmeden empty sınıfı eklenmemeli; genişlik timeLeft * 100 / TOTAL olmalı.");
